SET client_encoding = 'UTF8';
-- =====================================================================
-- QuickBasket practice database  (fictional Delhi-NCR quick-commerce company)
-- Data Analytics track, Module 0.  PostgreSQL 13+.
-- Run this whole file once inside an EMPTY database called quickbasket.
-- Data covers 1 Jan 2025 to 30 Sep 2026. All people and emails are made up.
-- =====================================================================

DROP TABLE IF EXISTS deliveries, order_items, orders, riders, customers, products, categories, stores, cities CASCADE;

CREATE TABLE cities (
    city_id     INT PRIMARY KEY,
    city_name   VARCHAR(50) NOT NULL,
    state       VARCHAR(50) NOT NULL
);

CREATE TABLE stores (
    store_id    INT PRIMARY KEY,
    store_name  VARCHAR(60) NOT NULL,
    city_id     INT NOT NULL REFERENCES cities(city_id),
    area        VARCHAR(60),
    opened_on   DATE NOT NULL
);

CREATE TABLE categories (
    category_id   INT PRIMARY KEY,
    category_name VARCHAR(60) NOT NULL
);

CREATE TABLE products (
    product_id     INT PRIMARY KEY,
    product_name   VARCHAR(80) NOT NULL,
    category_id    INT NOT NULL REFERENCES categories(category_id),
    brand          VARCHAR(60),
    unit           VARCHAR(30),
    mrp            NUMERIC(10,2) NOT NULL,
    selling_price  NUMERIC(10,2) NOT NULL,
    cost_price     NUMERIC(10,2) NOT NULL,
    launched_on    DATE NOT NULL
);

CREATE TABLE customers (
    customer_id          INT PRIMARY KEY,
    full_name            VARCHAR(80) NOT NULL,
    gender               CHAR(1),            -- M / F / NULL (not shared)
    birth_year           INT,                -- NULL for some customers
    email                VARCHAR(120),
    city_id              INT NOT NULL REFERENCES cities(city_id),
    home_store_id        INT NOT NULL REFERENCES stores(store_id),
    signup_date          DATE NOT NULL,
    acquisition_channel  VARCHAR(30)
);

CREATE TABLE riders (
    rider_id      INT PRIMARY KEY,
    rider_name    VARCHAR(80) NOT NULL,
    store_id      INT NOT NULL REFERENCES stores(store_id),
    joined_on     DATE NOT NULL,
    vehicle_type  VARCHAR(30)
);

CREATE TABLE orders (
    order_id         INT PRIMARY KEY,
    customer_id      INT NOT NULL REFERENCES customers(customer_id),
    store_id         INT NOT NULL REFERENCES stores(store_id),
    order_ts         TIMESTAMP NOT NULL,
    status           VARCHAR(20) NOT NULL,   -- Delivered / Cancelled / Returned
    payment_method   VARCHAR(20) NOT NULL,   -- UPI / Card / COD / Wallet
    coupon_code      VARCHAR(20),            -- NULL when no coupon used
    item_total       NUMERIC(10,2) NOT NULL, -- sum of quantity * unit_price
    discount_amount  NUMERIC(10,2) NOT NULL,
    delivery_fee     NUMERIC(10,2) NOT NULL,
    total_amount     NUMERIC(10,2) NOT NULL  -- item_total - discount + delivery_fee
);

CREATE TABLE order_items (
    order_item_id  INT PRIMARY KEY,
    order_id       INT NOT NULL REFERENCES orders(order_id),
    product_id     INT NOT NULL REFERENCES products(product_id),
    quantity       INT NOT NULL,
    unit_price     NUMERIC(10,2) NOT NULL
);

-- Cancelled orders have NO row here (useful later for LEFT JOIN practice)
CREATE TABLE deliveries (
    order_id          INT PRIMARY KEY REFERENCES orders(order_id),
    rider_id          INT NOT NULL REFERENCES riders(rider_id),
    promised_minutes  INT NOT NULL,
    actual_minutes    INT NOT NULL,
    delivered_ts      TIMESTAMP NOT NULL,
    rating            INT                     -- 1-5, NULL if customer did not rate
);


